    [8, 1, 1, 1, 0, 1, 1, 1, 1],
    [4, 1, 1, 3, 2, 0, 6, 1, 1]
]

def get_neighbors(grid, r, c):
    rows, cols = len(grid), len(grid[0])
    result = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result.append((nr, nc, grid[nr][nc]))
    return result

output = [[0]*9 for _ in range(9)]
for r in range(9):
    for c in range(9):
        if grid[r][c] != 1:
            output[r][c] = grid[r][c]
        else:
            neighbors = get_neighbors(grid, r, c)
            non_one_values = [v for (_, _, v) in neighbors if v != 1]
            # Use median or mode
            if not non_one_values:
                output[r][c] = 1  # keep as 1 if no non-1 neighbors
            elif len(non_one_values) == 1:
                output[r][c] = non_one_values[0]
            elif len(set(non_one_values)) == 1:
                output[r][c] = non_one_values[0]
            else:
                # Multiple different values - use most frequent
                from collections import Counter
                counts = Counter(non_one_values)
                output[r][c] = counts.most_common(1)[0][0]

print("Output replacing 1s with majority non-1 neighbor:")
for row in output:
    print(row)

