# BFS to count connected components of non-1 values
def count_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    count = 0

    def bfs(start_r, start_c):
        queue = [(start_r, start_c)]
        visited[start_r][start_c] = True
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] != 1:
                        visited[nr][nc] = True
                        queue.append((nr, nc))

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and grid[r][c] != 1:
                count += 1
                bfs(r, c)
    return count

num_objects = count_components(grid)
print(f"Number of connected components (non-1): {num_objects}")

# What if each cell becomes num_objects if it's a 1, otherwise stays same?
output_simple = []
for r in range(9):
    row = []
    for c in range(9):
